{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "C12, a benzamidine/carboxylate analogue with the highest transfer score, was reported to have absolute oral bioavailability not high enough for oral use in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "C28 (perindoprilat) had 19 ± 7% absolute oral bioavailability in young healthy subjects after oral prodrug dosing, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "C13 (revefenacin) had <3% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "C04 (emixustat) showed low oral bioavailability in healthy subjects, with parent concentrations far below total 14C.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "C24 (avanafil) had 8–10% oral bioavailability in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "C22, a highly transferable folate analogue, had 41 ± 18% absolute bioavailability in humans, above the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "C03 (tiopronin) had 63% absolute bioavailability in healthy subjects, above the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "C10 (sulpiride) had 27–34% absolute oral bioavailability in humans, above the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "C26 (L-arginine) had 68 ± 9% absolute oral bioavailability in healthy male subjects at 6 g, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, fully ionized zwitterionic benzamidine peptidomimetic. The closest high-transfer analogue (C12) and perindoprilat (C28) show low or below-threshold oral bioavailability, and revefenacin, emixustat, and avanafil reinforce low F. High-bioavailability analogues (folate, tiopronin, sulpiride, arginine) are mechanistically or structurally distinct and do not outweigh the low evidence. Therefore, F >= 20% is unlikely.",
  "evidence_gaps": [
    "No direct experimental F measurement for the query molecule itself.",
    "C12 is reported qualitatively as 'not high enough for oral use' without an exact F value.",
    "Potential transporter-mediated absorption of the benzamidine/guanidine moiety is not experimentally characterized for the query.",
    "Dose-dependent arginine bioavailability and folate transporter effects create uncertainty in extrapolating high-bioavailability analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

